#include <bits/stdc++.h>
using namespace std;

template <typename T> class BinaryTreeNode {
public:
    T data;
    BinaryTreeNode<T> *left, *right;
    BinaryTreeNode(T data) { this->data = data; left = right = NULL; }
};

// Read a tree in level order (-1 = no child)
template <class N> N* readTree() {
    int v; cin >> v;
    if (v == -1) return NULL;
    N* root = new N(v);
    queue<N*> q; q.push(root);
    while (!q.empty()) {
        N* p = q.front(); q.pop();
        int l, r; cin >> l >> r;
        if (l != -1) { p->left = new N(l); q.push(p->left); }
        if (r != -1) { p->right = new N(r); q.push(p->right); }
    }
    return root;
}

